import sys

s = sys.stdin.readline().strip()
n = len(s)
total = 0
for length in range(1, n + 1):
    best = 1
    for d in range(1, length + 1):
        if length % d:
            continue
        ok = True
        for i in range(d, length):
            if s[i] != s[i - d]:
                ok = False
                break
        if ok:
            best = length // d
            break
    total += best
print(total)
